"""Twenty original lung-function interpretation and diagnostic-procedure questions."""
from qbank_authoring import question,ref,finalize
SP=ref('ATS/ERS: Standardization of Spirometry, 2019','https://pmc.ncbi.nlm.nih.gov/articles/PMC6794117/')
IN=ref('ERS/ATS: Interpretive Strategies for Routine Lung Function Tests, 2022','https://publications.ersnet.org/content/erj/60/1/2101499')
LV=ref('ERS/ATS: Standardization of Lung Volume Measurement, 2023','https://doi.org/10.1183/13993003.01519-2022')
BO=ref('BTS: Diagnostic Flexible Bronchoscopy in Adults','https://thorax.bmj.com/content/68/Suppl_1/i1')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('Which spirometry quality goal is appropriate for an adult under ATS/ERS 2019 standards?', 'At least three acceptable maneuvers with the largest two FEV1 values and largest two FVC values each within 150 mL',[
 ('One forced expiration regardless of cough or effort','This is insufficient quality assessment.'),('Identical FEV1 and FVC are required','They measure different volumes and need not be identical.'),('A normal-looking printed value removes the need to inspect the curves','Artifacts can produce misleading numerical results.')],
 'Interpretation begins with acceptability and repeatability', '**The top two values are compared separately for FEV1 and FVC.**',['A good start, appropriate expiration and absence of relevant artifacts matter.','A lower quality grade must be acknowledged rather than hidden.'], '**Inspect the curves as well as the report.**',['Cough, leak or early termination can distort results.','A technically poor study can mimic disease or conceal it.'],[['Acceptability','Maneuver quality'],['Repeatability','Top two values within 150 mL in adults'],['Interpretation','Use quality context']],[SP])
q('A patient coughs during the first second of a forced expiratory maneuver. Which parameter is particularly compromised?', 'FEV1',[
 ('TLC directly measured by that maneuver','Spirometry alone does not directly measure TLC.'),('Hemoglobin concentration','A cough does not measure blood hemoglobin.'),('Pleural fluid pH','This is unrelated to the spirometric maneuver.')],
 'An artifact early in expiration can invalidate the timed volume', '**First-second cough can make FEV1 unacceptable.**',['FVC acceptability is judged separately.','Repeat the maneuver with coaching when safe and feasible.'], '**Avoid diagnosing obstruction from an artifact.**',['Review the flow-volume and volume-time curves.','Report residual limitations if adequate quality cannot be obtained.'],[['Artifact timing','First second'],['Main concern','FEV1 validity'],['Response','Repeat and review quality']],[SP])
q('Under ERS/ATS interpretation principles, which result supports airflow obstruction?', 'FEV1/FVC below the appropriate lower limit of normal',[
 ('Low FVC with a preserved ratio alone','That can reflect restriction, air trapping, poor effort or a nonspecific pattern.'),('Low TLC with a preserved ratio alone','This establishes a restrictive pattern rather than obstruction.'),('Isolated low DLCO with normal spirometry','This requires a different physiological differential.')],
 'Use the ratio to identify an obstructive ventilatory pattern', '**Compare with appropriate reference limits.**',['A fixed ratio is used in specific disease frameworks such as GOLD, but is not identical to LLN interpretation.','Age affects expected ratio values.'], '**Then identify severity, response and cause.**',['Obstruction alone does not distinguish asthma from COPD.','Use history, exposure and additional testing.'],[['Obstruction','Low FEV1/FVC'],['Restriction','Low TLC'],['Diffusion defect','DLCO interpretation']],[IN])
q('FEV1/FVC and FVC are both reduced. What is needed to distinguish true mixed obstruction/restriction from obstruction with air trapping?', 'Lung-volume measurement, particularly TLC',[
 ('Assume every low FVC proves restriction','Air trapping can lower the exhaled vital capacity.'),('Use sputum color to define TLC','This is not a lung-volume measurement.'),('Ignore the low ratio once FVC is reduced','Obstruction remains part of the pattern.')],
 'A low FVC is not equivalent to a low TLC', '**True mixed impairment includes obstruction and a reduced TLC.**',['A normal or high TLC with elevated residual volume favors air trapping.','Poor effort must also be excluded.'], '**Interpret the complete study rather than assigning two diseases from spirometry alone.**',['Check quality and reference ranges.','Relate the pattern to imaging and the clinical history.'],[['Low ratio + low FVC','Not enough to prove mixed defect'],['Low TLC','Confirms restriction component'],['High RV with preserved TLC','Supports air trapping']],[IN,LV])
q('A patient has FEV1/FVC below LLN, TLC above normal and markedly increased RV/TLC. Which interpretation is most consistent?', 'Obstruction with hyperinflation and air trapping',[
 ('Pure restriction','TLC is increased, not reduced.'),('Normal lung volumes','Both TLC and the retained-gas proportion are abnormal.'),('A low diffusion capacity established by these volumes alone','DLCO requires a separate measurement.')],
 'Static volumes reveal information not contained in the forced ratio', '**High TLC supports hyperinflation and high RV/TLC supports retained gas.**',['These findings commonly accompany obstructive disease.','The clinical severity depends on symptoms and other physiology too.'], '**Connect the result to functional consequences.**',['Hyperinflation can increase inspiratory load.','Treatment and exercise response may change dynamic mechanics.'],[['FEV1/FVC','Obstruction'],['TLC','Hyperinflation'],['RV/TLC','Air trapping']],[IN,LV],style='clinical_scenario')
q('Under the ERS/ATS 2022 bronchodilator-response calculation, FEV1 rises by 0.36 L and predicted FEV1 is 3.0 L. What is the response as percent predicted?', '12%',[
 ('10.8%','The required calculation is 0.36 divided by 3.0 times 100.'),('36%','This does not use the predicted-volume denominator correctly.'),('It cannot be calculated without the baseline FEV1','This particular formula uses predicted, not baseline, value as the denominator.')],
 'Name the bronchodilator framework before applying its cutoff', '**The ERS/ATS 2022 response is change divided by predicted value times 100.**',['0.36 / 3.0 × 100 = 12%.','A change greater than 10% predicted is significant in that framework.'], '**Do not confuse it with older or disease-specific criteria.**',['The older 12% plus 200-mL rule uses a different denominator and threshold structure.','A response supports physiology but does not alone identify the disease.'],[['Change','0.36 L'],['Predicted','3.0 L'],['Response','12% predicted']],[IN])
q('What does a positive bronchodilator response establish by itself?', 'Variable airflow physiology, not a definitive distinction between asthma and COPD',[
 ('Asthma to the exclusion of every other disease','COPD and other settings can show a response.'),('Permanent absence of future obstruction','A single response does not establish that.'),('That maintenance treatment can always be stopped','Treatment decisions require the diagnosis and risk assessment.')],
 'Physiological reversibility is not a unique disease label', '**Interpret the response with symptoms and longitudinal evidence.**',['Some asthma patients have no response at one visit.','Some COPD patients show a significant response.'], '**Use the full diagnostic framework.**',['Check treatment exposure and test quality.','Repeat or use other objective tests when uncertainty remains.'],[['Positive response','Supports variable physiology'],['Negative response','Does not exclude asthma'],['Diagnosis','Clinical and longitudinal integration']],[IN])
q('Why can helium-dilution lung volumes underestimate total thoracic gas in severe obstruction?', 'Poorly communicating trapped gas may not equilibrate with the test gas',[
 ('Helium dilution directly measures every closed gas space','The gas must communicate sufficiently with the sampled system.'),('Spirometry can independently measure the missing residual volume','Spirometry does not directly measure RV.'),('The method always overestimates all trapped gas','The described limitation is underestimation of poorly communicating gas.')],
 'Different volume methods measure gas under different assumptions', '**Gas-dilution techniques depend on gas mixing.**',['Severe obstruction and noncommunicating regions impair equilibration.','Body plethysmography measures thoracic gas through a different physical method.'], '**Compare results with quality and disease context.**',['Plethysmography also has technical pitfalls in severe obstruction.','Do not treat disagreement as proof that one unreviewed result is correct.'],[['Gas dilution','Communicating gas'],['Severe obstruction','Mixing limitation'],['Plethysmography','Different thoracic-gas method']],[LV])
q('Which condition can reduce measured DLCO without intrinsic alveolar fibrosis?', 'Anemia',[
 ('Polycythemia as the expected lowering mechanism','More hemoglobin can increase measured CO uptake.'),('Alveolar hemorrhage as the usual isolated lowering mechanism','Intra-alveolar hemoglobin can raise measured uptake.'),('A normal hemoglobin concentration as proof of low DLCO','Normal hemoglobin does not itself explain a low result.')],
 'DLCO depends on blood as well as membrane properties', '**Hemoglobin availability affects carbon monoxide transfer.**',['Use an appropriate hemoglobin adjustment.','Altitude, carboxyhemoglobin and technique can also influence interpretation.'], '**Do not diagnose ILD from an uncontextualized low DLCO.**',['Consider emphysema and pulmonary vascular disease.','Integrate spirometry, volumes, imaging and clinical findings.'],[['Anemia','Can lower measured DLCO'],['Fibrosis / emphysema','Different pulmonary mechanisms'],['Interpretation','Adjustment and clinical integration']],[IN])
q('A patient has low FEV1/FVC and markedly reduced DLCO. Which phenotype is more strongly suggested than uncomplicated asthma?', 'Emphysema',[
 ('Pure variable asthma with no other process','DLCO is often preserved or increased in asthma.'),('Isolated vocal-cord dysfunction','It does not typically explain this diffusion impairment.'),('Normal lung physiology','Both measures are abnormal.')],
 'Combine airflow and diffusion information', '**Loss of alveolar-capillary surface area can lower DLCO in emphysema.**',['The pattern is suggestive, not pathognomonic.','Anemia, vascular disease and combined fibrosis can contribute.'], '**Use imaging and history to establish the phenotype.**',['Smoking and exposure history are relevant.','A low DLCO may also explain exertional desaturation.'],[['Obstruction plus low DLCO','Emphysema is an important possibility'],['Asthma alone','DLCO often preserved'],['Confirmation','Clinical and imaging context']],[IN],style='clinical_scenario')
q('Spirometry and lung volumes are near normal, but DLCO is substantially reduced. Which differential is important?', 'Pulmonary vascular disease, early parenchymal disease and anemia',[
 ('Normal pulmonary health established by spirometry alone','Diffusion impairment can be clinically meaningful.'),('Asthma proven by isolated low DLCO','This is not a specific asthma pattern.'),('Restriction confirmed despite a normal TLC','A reduced TLC is needed to establish restriction.')],
 'Normal volumes do not exclude important gas-transfer disease', '**An isolated low DLCO has a focused but nonunique differential.**',['Check hemoglobin and test quality.','Pulmonary vascular or early interstitial disease may precede marked volume changes.'], '**Investigate according to symptoms and risk.**',['Echocardiography, CT or exercise testing may be relevant.','Do not select a diagnosis from one number alone.'],[['Blood','Anemia'],['Vascular','Pulmonary vascular disease'],['Parenchymal','Early ILD or selected combined disease']],[IN])
q('A reproducible flow-volume loop has flattening of the inspiratory limb with a relatively preserved expiratory limb. Which mechanism is most consistent?', 'Variable extrathoracic upper-airway obstruction',[
 ('Variable intrathoracic obstruction','This more often flattens the expiratory limb.'),('Fixed large-airway obstruction','Both limbs are typically flattened.'),('Pure restrictive physiology established by loop shape alone','Restriction requires lung-volume confirmation.')],
 'Pressure relationships determine where variable obstruction appears', '**An extrathoracic airway can narrow during inspiration.**',['Inducible laryngeal obstruction is one possible cause.','Suboptimal effort can mimic flattening.'], '**Confirm the finding and evaluate the airway when appropriate.**',['Repeat quality maneuvers.','Laryngoscopy or imaging may be needed depending on the suspected lesion.'],[['Extrathoracic variable','Inspiratory flattening'],['Intrathoracic variable','Expiratory flattening'],['Fixed','Both limbs flattened']],[IN,SP])
q('Which flow-volume loop pattern suggests a fixed central airway obstruction?', 'Plateauing of both inspiratory and expiratory limbs',[
 ('Inspiratory flattening alone','This favors a variable extrathoracic process.'),('Expiratory flattening alone','This favors a variable intrathoracic process.'),('A normal loop with a low hemoglobin','That may alter DLCO but is not the fixed-obstruction loop.')],
 'A fixed narrowing limits flow in both directions', '**Tracheal stenosis is one possible cause.**',['Loop quality and reproducibility are essential.','Symptoms can be mistaken for asthma.'], '**Investigate suspected central obstruction directly.**',['Imaging and bronchoscopy may define the lesion.','Do not escalate inhalers indefinitely when the pattern suggests a mechanical airway problem.'],[['Fixed lesion','Both limbs limited'],['Variable lesion','Phase-dependent limitation'],['Next step','Anatomical airway assessment']],[IN,BO])
q('What is a useful role of cardiopulmonary exercise testing in otherwise unexplained exertional dyspnea?', 'Integrating ventilatory, circulatory and metabolic responses to help identify the limiting mechanism',[
 ('Proving a single diagnosis from peak heart rate alone','The test requires integrated interpretation.'),('Replacing all resting imaging and history','It complements rather than erases prior assessment.'),('Measuring a pulmonary nodule’s histology','That requires a different diagnostic approach.')],
 'Exercise can expose abnormalities not apparent at rest', '**CPET examines oxygen uptake, ventilation and cardiovascular responses together.**',['Ventilatory inefficiency, breathing reserve and oxygen-pulse patterns contribute.','Effort and protocol quality affect interpretation.'], '**Use patterns to guide targeted further evaluation.**',['Deconditioning, circulatory disease and ventilatory limitation can overlap.','Avoid treating one index as uniquely diagnostic.'],[['Measures','Ventilation, gas exchange and circulation'],['Use','Mechanism of exercise limitation'],['Limit','Patterns need clinical integration']],[IN])
q('Which problem must be assessed before sedated diagnostic bronchoscopy?', 'Baseline oxygenation, cardiopulmonary stability, medication-related bleeding risk and the planned sampling procedure',[
 ('Only the patient’s height','This is not a sufficient safety assessment.'),('No preprocedure review if a flexible scope is used','Flexible bronchoscopy still has sedation and sampling risks.'),('A normal chest radiograph as proof that all complications are impossible','Imaging does not eliminate procedural risk.')],
 'Risk depends on the patient and what will be sampled', '**BAL, endobronchial biopsy and transbronchial biopsy have different risk profiles.**',['Hypoxemia and sedation-related events require preparation.','Anticoagulant and antiplatelet decisions depend on the drug, procedure and thrombosis risk.'], '**Use a defined monitoring and rescue plan.**',['Obtain informed consent and appropriate expertise.','Do not apply a generic medication interruption rule without checking the clinical context.'],[['Patient','Oxygenation and stability'],['Procedure','Sampling-related risk'],['Plan','Monitoring and management of complications']],[BO])
q('Which complication is particularly relevant after a transbronchial lung biopsy?', 'Pneumothorax',[
 ('Inevitable permanent diaphragmatic paralysis','This is not an expected universal consequence.'),('Guaranteed zero bleeding because the biopsy is bronchoscopic','Bleeding is a recognized risk.'),('Development of a CFTR mutation','The procedure does not create inherited CF.')],
 'Sampling peripheral lung carries pleural and vascular risks', '**Transbronchial biopsy can cause pneumothorax and hemorrhage.**',['Risk varies with technique and patient factors.','New chest pain, hypoxemia or breathlessness requires assessment.'], '**Monitor according to the procedure protocol and clinical course.**',['Use imaging when indicated to assess complications.','Ensure clear postprocedure advice and access to review.'],[['Pleural complication','Pneumothorax'],['Vascular complication','Bleeding'],['Monitoring','Symptoms, oxygenation and indicated imaging']],[BO])
q('Progressively bloodier sequential BAL aliquots are obtained from a patient with diffuse opacities and falling hemoglobin. Which syndrome is suggested?', 'Diffuse alveolar hemorrhage',[
 ('A simple proximal traumatic bleed as the only possible explanation','An increasingly bloody sequential pattern with this syndrome supports alveolar bleeding.'),('Pure cardiogenic transudative pleural effusion','BAL samples the lower respiratory tract, not pleural fluid.'),('CF established by lavage color','CF diagnosis uses a different framework.')],
 'Serial lavage appearance can localize a bleeding process', '**Increasing hemorrhagic return supports alveolar hemorrhage.**',['Hemosiderin-laden macrophages may appear with time.','Hemoptysis can be absent.'], '**Investigate cause and stabilize gas exchange.**',['Immune capillaritis, drugs, infection and cardiac causes are among the possibilities.','Do not start cause-specific immunosuppression without considering infection and the broader presentation.'],[['Clinical clues','Diffuse opacities and hemoglobin fall'],['BAL','Progressively bloody aliquots'],['Next step','Stabilization and etiological work-up']],[BO],style='clinical_scenario')
q('In suspected endobronchial obstruction with recurrent focal pneumonia, what is a useful role of bronchoscopy?', 'Direct airway inspection with targeted sampling when indicated',[
 ('Measurement of total lung capacity as its main purpose','Lung volumes are measured by pulmonary-function techniques.'),('Definitive exclusion of every peripheral lesion by a normal central airway view','A normal visible airway does not exclude all peripheral disease.'),('Replacement of all CT imaging in every patient','CT and bronchoscopy provide complementary information.')],
 'An airway procedure can answer a localized anatomical question', '**Bronchoscopy can identify a tumor, foreign body or stenosis.**',['Sampling is selected according to the visible lesion and purpose.','CT can guide planning and reveal extraluminal disease.'], '**Choose a procedure that changes management.**',['Balance yield with bleeding and respiratory risks.','Preserve adequate tissue for the intended pathological testing.'],[['Inspection','Endobronchial anatomy'],['Sampling','Targeted diagnostic material'],['CT','Complementary structural assessment']],[BO],style='clinical_scenario')
q('Why is bronchoalveolar lavage cellular differential alone usually insufficient to establish a specific ILD diagnosis?', 'Cell patterns overlap between diseases and are influenced by timing, smoking, treatment and sampling',[
 ('BAL never provides useful information','It can support a differential or detect infection and other processes.'),('Any lymphocytosis proves sarcoidosis','Several disorders can produce lymphocytic lavage.'),('Any eosinophil proves invasive fungal disease','Eosinophilic patterns have multiple causes and require context.')],
 'A cellular pattern is a clue rather than a universal disease signature', '**Lymphocytic, eosinophilic or neutrophilic patterns narrow the differential.**',['The magnitude and clinical phenotype matter.','Microbiology and imaging answer additional questions.'], '**Integrate BAL into a multidisciplinary assessment.**',['Consider whether biopsy would add useful information at acceptable risk.','Do not let an isolated ratio replace the full diagnosis.'],[['BAL cells','Supportive pattern'],['Other data','Exposure, CT, physiology and microbiology'],['Diagnosis','Integrated assessment']],[BO,IN])
q('Which statement best describes the lower limit of normal used in modern PFT interpretation?', 'A reference-based statistical boundary that must be interpreted with pretest probability and test quality',[
 ('An absolute line that proves disease in every person below it','Some healthy individuals fall below a statistical boundary.'),('A universal 80% predicted threshold for every index','Different measures and distributions require appropriate reference limits.'),('A value independent of the chosen reference equation','Reference equations affect predicted values and z-scores.')],
 'Statistical abnormality and clinical disease are related but distinct', '**Use appropriate reference equations and z-scores where applicable.**',['The conventional LLN is often the fifth percentile.','Multiple testing increases the chance of at least one outlying result.'], '**Interpret the pattern and longitudinal change.**',['A borderline value is not a diagnosis by itself.','Quality, symptoms and prior measurements determine its significance.'],[['LLN','Reference-distribution boundary'],['Below LLN','Raises concern, not independent proof'],['Interpretation','Quality and clinical probability']],[IN])

if __name__=='__main__':finalize('Respiratory system',12,'Pulmonary Function and Diagnostic Procedures','resp-pft',rows,20)
